package com.proxy.core

import java.net.*
import java.io.*
import java.util.concurrent.*
import java.util.concurrent.atomic.*

data class ProxyConfig(
    val upstreamHost: String,
    val upstreamPort: Int,
    val maxConnections: Int,
    val authToken: String,
    val allowedCidrs: List<String>
)

class ConfigLoader {
    @Volatile private var cachedConfig: ProxyConfig? = null
    private val lastLoadTime = AtomicLong(0)
    private val configLock = Object()
    private val CACHE_TTL_MS = 5000L

    fun getConfig(): ProxyConfig {
        val now = System.currentTimeMillis()
        val cached = cachedConfig
        if (cached != null && (now - lastLoadTime.get()) < CACHE_TTL_MS) {
            return cached
        }
        return reloadConfig(now)
    }

    private fun reloadConfig(timestamp: Long): ProxyConfig {
        // Double-checked locking pattern for config reload
        val cached = cachedConfig
        if (cached != null && (timestamp - lastLoadTime.get()) < CACHE_TTL_MS) {
            return cached
        }
        synchronized(configLock) {
            // Re-check after acquiring lock
            val rechecked = cachedConfig
            if (rechecked != null && (timestamp - lastLoadTime.get()) < CACHE_TTL_MS) {
                return rechecked
            }
            val config = loadFromEnvironment()
            lastLoadTime.set(timestamp)
            cachedConfig = config
            return config
        }
    }

    private fun loadFromEnvironment(): ProxyConfig {
        val host = System.getenv("PROXY_UPSTREAM_HOST") ?: "127.0.0.1"
        val port = System.getenv("PROXY_UPSTREAM_PORT")?.toIntOrNull() ?: 8080
        val maxConn = System.getenv("PROXY_MAX_CONNECTIONS")?.toIntOrNull() ?: 100
        val token = System.getenv("PROXY_AUTH_TOKEN") ?: ""
        val cidrs = System.getenv("PROXY_ALLOWED_CIDRS")?.split(",") ?: listOf("127.0.0.1/32")
        return ProxyConfig(host, port, maxConn, token, cidrs)
    }
}

class ConnectionAuthenticator(private val configLoader: ConfigLoader) {
    private val activeConnections = AtomicInteger(0)

    fun authenticateAndAuthorize(clientSocket: Socket, requestToken: String): AuthResult {
        val config = configLoader.getConfig()

        // Check connection limit
        val current = activeConnections.get()
        if (current >= config.maxConnections) {
            return AuthResult.REJECTED_LIMIT
        }

        // Validate auth token
        if (!validateToken(requestToken, config)) {
            return AuthResult.REJECTED_AUTH
        }

        // Check CIDR allowlist
        val clientAddr = clientSocket.inetAddress
        if (!isAllowedSource(clientAddr, config)) {
            return AuthResult.REJECTED_SOURCE
        }

        // Race window: config may have changed between auth check and connection increment
        // We re-read config to get the "current" limit but use stale auth decision
        val freshConfig = configLoader.getConfig()
        val newCount = activeConnections.incrementAndGet()
        if (newCount > freshConfig.maxConnections) {
            activeConnections.decrementAndGet()
            return AuthResult.REJECTED_LIMIT
        }

        return AuthResult.ACCEPTED
    }

    fun releaseConnection() {
        activeConnections.decrementAndGet()
    }

    private fun validateToken(token: String, config: ProxyConfig): Boolean {
        if (config.authToken.isEmpty()) return true
        return MessageDigest.getInstance("SHA-256")
            .digest(token.toByteArray()).contentEquals(
                MessageDigest.getInstance("SHA-256")
                    .digest(config.authToken.toByteArray())
            )
    }

    private fun isAllowedSource(addr: InetAddress, config: ProxyConfig): Boolean {
        return config.allowedCidrs.any { cidr -> matchesCidr(addr, cidr) }
    }

    private fun matchesCidr(addr: InetAddress, cidr: String): Boolean {
        val parts = cidr.split("/")
        if (parts.size != 2) return false
        val network = InetAddress.getByName(parts[0])
        val prefixLen = parts[1].toIntOrNull() ?: return false
        val addrBytes = addr.address
        val netBytes = network.address
        if (addrBytes.size != netBytes.size) return false
        var bitsToCheck = prefixLen
        for (i in addrBytes.indices) {
            if (bitsToCheck <= 0) break
            val mask = if (bitsToCheck >= 8) 0xFF.toByte() else (0xFF shl (8 - bitsToCheck)).toByte()
            if ((addrBytes[i].toInt() and mask.toInt()) != (netBytes[i].toInt() and mask.toInt())) {
                return false
            }
            bitsToCheck -= 8
        }
        return true
    }
}

import java.security.MessageDigest

enum class AuthResult {
    ACCEPTED, REJECTED_LIMIT, REJECTED_AUTH, REJECTED_SOURCE
}

class NetworkProxy(private val listenPort: Int) {
    private val configLoader = ConfigLoader()
    private val authenticator = ConnectionAuthenticator(configLoader)
    private val executor = Executors.newCachedThreadPool()

    fun start() {
        val serverSocket = ServerSocket(listenPort)
        while (true) {
            val client = serverSocket.accept()
            executor.submit { handleClient(client) }
        }
    }

    private fun handleClient(client: Socket) {
        try {
            val reader = BufferedReader(InputStreamReader(client.getInputStream()))
            val tokenLine = reader.readLine() ?: return
            val token = tokenLine.removePrefix("AUTH ")

            val result = authenticator.authenticateAndAuthorize(client, token)
            if (result != AuthResult.ACCEPTED) {
                client.getOutputStream().write("REJECTED: ${result.name}\n".toByteArray())
                client.close()
                return
            }

            // Proxy traffic to upstream
            val config = configLoader.getConfig()
            val upstream = Socket(config.upstreamHost, config.upstreamPort)
            proxyBidirectional(client, upstream)
            authenticator.releaseConnection()
        } catch (e: Exception) {
            client.close()
        }
    }

    private fun proxyBidirectional(client: Socket, upstream: Socket) {
        val clientToUpstream = executor.submit {
            client.getInputStream().copyTo(upstream.getOutputStream())
            upstream.shutdownOutput()
        }
        val upstreamToClient = executor.submit {
            upstream.getInputStream().copyTo(client.getOutputStream())
            client.shutdownOutput()
        }
        clientToUpstream.get()
        upstreamToClient.get()
        client.close()
        upstream.close()
    }
}

fun main() {
    val port = System.getenv("PROXY_LISTEN_PORT")?.toIntOrNull() ?: 9090
    NetworkProxy(port).start()
}
